[~,ix1] = patternMatchCellArray(featLeg,{'jaw_xdisp_view2'},'all');
[~,ix2] = patternMatchCellArray(featLeg,{'jaw_ydisp_view2'},'all');
jx = kin(:, :, ix1);
jy = kin(:, :, ix2);



% tongue_tip_x = 0.5.*(t1x+t2x);
