cd /app && python3 -c "
import h5py
f='/app/data/Ephys_Behavior/data_structure_JEB13_2022-09-13.mat'
try:
    h=h5py.File(f,'r')
    print('v7.3 HDF5')
    print(list(h.keys()))
    def show(g,pre='',depth=0):
        if depth>2: return
        for k in g:
            it=g[k]
            if isinstance(it,h5py.Group):
                print(pre+k+'/ (group)')
                show(it,pre+'  ',depth+1)
            else:
                print(pre+k, it.shape, it.dtype)
    show(h['obj'])
except Exception as e:
    print('not hdf5',e)
"

