python3 -u -c "
import h5py, numpy as np, glob, os
def s(f,ds): return ''.join(chr(c) for c in np.array(ds).flatten())
def nclu_of(f,o):
    c=o['clu']
    arr=np.array(c).flatten()
    out=[]
    for r in arr:
        try: out.append(f[r]['quality'].shape[0])
        except Exception: out.append('?')
    return out
for d in ['Ephys_Behavior','RandomizedDelay_Ephys_Behavior']:
  print('=====',d)
  for fn in sorted(glob.glob(f'/app/data/{d}/data_structure_*.mat')):
    f=h5py.File(fn,'r'); o=f['obj']; bp=o['bp']
    N=int(np.array(bp['Ntrials']).flatten()[0])
    aw=np.array(bp['autowater']).flatten()
    # count blocks: runs of aw==1
    runs=np.diff(np.concatenate([[0],(aw==1).astype(int),[0]]))
    nblocks=int((runs==1).sum())
    locs=None
    for key in ['ex','meta']:
        if key in o and 'probe' in o[key]:
            try:
                locs=[s(f,f[r]) for r in np.array(o[key]['probe']['loc']).flatten()]; break
            except Exception: pass
    print(os.path.basename(fn)[15:-4], 'N=%d'%N, 'aw=%d'%np.nansum(aw), 'awblocks=%d'%nblocks, 'firstaw=%s'%(np.argmax(aw==1) if aw.max()>0 else -1), 'loc=',locs, 'nclu=',nclu_of(f,o), 'me=', 'me' in o)
    f.close()
"

