from convert_data import SESSIONS, load_obj, vec, select_clusters, select_trials
import numpy as np, warnings; warnings.filterwarnings('ignore')
import concurrent.futures as cf
def job(s):
    anm,date,probes,task=s
    o=load_obj(anm,date,task)
    n=int(vec(o['bp']['Ntrials'])[0])
    cl=select_clusters(o,probes)
    clu=o['clu']
    if isinstance(clu,dict): clu=[clu]
    has=np.zeros(n,bool); maxtr=0
    for p,i in cl:
        tn=clu[p]['trial']; tn=tn if isinstance(tn,list) else [tn]
        t=np.ravel(np.asarray(tn[i],float)).astype(int)
        t=t[(t>=1)&(t<=n)]
        has[t-1]=True
        if t.size: maxtr=max(maxtr,t.max())
    empty=np.flatnonzero(~has)
    return (f'{anm}_{date}', n, maxtr, int(empty.size), list(empty[:3]), list(empty[-3:]))
with cf.ProcessPoolExecutor(16) as ex:
    for r in ex.map(job,SESSIONS):
        if r[3]>0: print(r)
print('done')
